// Pure contracts shared by prototype controls, submission snapshots and import preview.
export function shotSpec(s,sh){return {model:s.generation?.model||s.models?.video?.name||'演示视频模型',aspect:s.generation?.aspect||s.aspect||'9:16',resolution:s.generation?.resolution||s.resolution||'1080P',...sh.generation,duration:sh.duration}}
export function composeShot(s,sh){const style=s.styles[s.styleIndex],dialogues=(sh.dialogues||[]).map(({audio,...d})=>({...d})),ids=[...sh.prompt.matchAll(/@\[([^\]]+)\]/g)].map(m=>m[1]);const imageReferences=[...new Set(ids)].map(id=>{const a=sh.assets.find(a=>a.id===id)||sh.previousFrame;return {refId:id,name:a?.name||'上一镜尾帧',kind:a?.kind||'尾帧',description:a?.description||'',version:a?.version||1,image:a?.image||null}});return {imageReferences,style:{name:style.name,text:style.text,version:s.styleVersion},dialogues,bindings:{assetIds:ids,dialogueIds:dialogues.map(d=>d.id)},prompt:[sh.prompt,`【绑定图片】\n${imageReferences.map(a=>`[${a.refId}] ${a.kind} · ${a.name}：${a.description}`).join('\n')}`,`【项目风格 · ${style.name}】\n${style.text}`,`【绑定台词 · 以本区为准】\n${dialogues.map(d=>`[${d.id}] ${d.speaker}（${d.emotion}）：${d.text}`).join('\n')}`].join('\n\n')}}
export const importTemplate={format:'shortfilm-storyboard-import',schemaVersion:1,shots:[{id:'shot-1',duration:5,prompt:'中景，角色走进场景，拿起道具。参考 @[person-1] @[scene-1] @[prop-1] @[position-1]',assets:[{id:'person-1',kind:'角色',name:'主角',description:'角色外貌与服装'},{id:'scene-1',kind:'场景',name:'房间',description:'室内环境与光线'},{id:'prop-1',kind:'道具',name:'信件',description:'关键道具外观'},{id:'position-1',kind:'站位',name:'门边站位',description:'角色面向室内'}],dialogues:[{id:'line-1',speaker:'主角',emotion:'自然',text:'终于回来了。',voice:'默认音色'}],bindings:{assetIds:['person-1','scene-1','prop-1','position-1'],dialogueIds:['line-1']}}]};
const str=(max=10000)=>({type:'string',minLength:1,maxLength:max});
const id={...str(100),pattern:'^[A-Za-z][A-Za-z0-9_-]*$'};
const object=(properties,required=Object.keys(properties))=>({type:'object',additionalProperties:false,properties,required});
const array=(items,minItems=1,maxItems=100)=>({type:'array',items,minItems,maxItems});
export const importSchema={$schema:'https://json-schema.org/draft/2020-12/schema',title:'AI短片工坊 分镜导入包 v1',...object({format:{const:'shortfilm-storyboard-import'},schemaVersion:{const:1},shots:array(object({id,duration:{type:'number',exclusiveMinimum:0,maximum:600},prompt:str(),assets:array(object({id,kind:{enum:['角色','场景','道具','站位']},name:str(100),description:str(2000)}),0,100),dialogues:array(object({id,speaker:str(100),emotion:str(100),text:{type:'string',maxLength:10000},voice:str(100)})),bindings:object({assetIds:array(id,0),dialogueIds:array(id)}),generation:object({model:str(200),aspect:{enum:['9:16','16:9','1:1']},resolution:{enum:['720P','1080P','4K']}},[])},['id','duration','prompt','assets','dialogues','bindings']),1,100)})};
export function validateImport(value){
 function walk(v,s,p){const fail=m=>{throw Error(`${p}: ${m}`)};if(s.const!==undefined&&v!==s.const)fail('版本或格式不匹配');if(s.enum&&!s.enum.includes(v))fail('不支持的选项');if(s.type==='object'){if(!v||typeof v!=='object'||Array.isArray(v))fail('应为对象');for(const k of Object.keys(v))if(!Object.hasOwn(s.properties,k))fail(`未知字段 ${k}`);for(const k of s.required||[])if(!Object.hasOwn(v,k))fail(`缺少 ${k}`);for(const [k,x] of Object.entries(v))walk(x,s.properties[k],`${p}.${k}`)}if(s.type==='array'){if(!Array.isArray(v))fail('应为数组');if(v.length<s.minItems||v.length>s.maxItems)fail('数组数量超出限制');v.forEach((x,i)=>walk(x,s.items,`${p}[${i}]`))}if(s.type==='string'){if(typeof v!=='string'||v.length>(s.maxLength??Infinity)||v.trim().length<(s.minLength??0))fail('文本为空或过长');if(s.pattern&&!new RegExp(s.pattern).test(v))fail('ID只能含英文字母、数字、下划线和连字符，且以字母开头')}if(s.type==='number'&&(typeof v!=='number'||!Number.isFinite(v)||v<=s.exclusiveMinimum||v>s.maximum))fail('时长应大于0且不超过600秒');}
 walk(value,importSchema,'$');const all=new Set();for(const [i,sh] of value.shots.entries()){for(const x of [sh,...sh.assets,...sh.dialogues]){if(all.has(x.id))throw Error(`shots[${i}]: 重复ID ${x.id}`);all.add(x.id)}const same=(a,b)=>a.length===new Set(a).size&&a.length===new Set(b).size&&a.every(x=>b.includes(x));const refs=[...sh.prompt.matchAll(/@\[([^\]]+)\]/g)].map(m=>m[1]);if(!same(sh.bindings.assetIds,[...new Set(refs)])||sh.bindings.assetIds.some(x=>!sh.assets.some(a=>a.id===x)))throw Error(`shots[${i}]: 图片引用与bindings不一致或不存在`);if(!same(sh.bindings.dialogueIds,sh.dialogues.map(d=>d.id)))throw Error(`shots[${i}]: 台词绑定缺失或重复`);if(sh.prompt.replace(/@\[[^\]]+\]/g,'').includes('@'))throw Error(`shots[${i}]: 未识别的图片引用`)}return value;
}
